insert into public.posts (id, created_at, deleted_at, user_id, type, place_label, place_ref, title, text, rating, photo_paths, trip_id, visibility) values
  ('de300000-0000-4000-8000-ec8c9d2ba52c', now() - interval '2880 minutes', null, 'de300000-0000-4000-8000-3d90ebd1bf45', 'tip', 'Lisboa', null, null, 'O elétrico 28 lota a partir das 10h. Pega no Martim Moniz antes das 9h que dá pra sentar.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-ef8c9d2baa45', now() - interval '7200 minutes', null, 'de300000-0000-4000-8000-8032b10af231', 'itinerary', 'Kyoto', null, null, '5 dias em Kyoto na época das cerejeiras: templos bem cedo, Gion à noite, Arashiyama num dia de semana.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-ee8c9d2ba892', now() - interval '10080 minutes', null, 'de300000-0000-4000-8000-8492f3476a98', 'review', 'Florianópolis', null, null, 'Ostras no Ribeirão seguem impecáveis, mas no fim de semana precisa reservar. Fui sem e esperei 1h.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-746c1fefaa60', now() - interval '4320 minutes', null, 'de300000-0000-4000-8000-3d90ebd1bf45', 'tip', 'Miradouro da Senhora do Monte', null, null, 'Chega 40 minutos antes do pôr do sol pra pegar lugar na mureta.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-756c1fefac13', now() - interval '20160 minutes', null, 'de300000-0000-4000-8000-8b65da21c2e6', 'tip', 'Miradouro da Senhora do Monte', null, null, 'Sobe de elétrico 28 até a Graça e faz o resto a pé, são 5 minutos.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-b3e06e323e4e', now() - interval '2880 minutes', null, 'de300000-0000-4000-8000-d76073f36362', 'tip', 'Portugal', null, 'Lisboa em agosto: o que muda', 'Muitos restaurantes de bairro fecham pra férias na segunda quinzena. Confira antes de ir.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-b2e06e323c9b', now() - interval '5760 minutes', null, 'de300000-0000-4000-8000-13515aeb9e7d', 'tip', 'Japão', null, 'JR Pass ainda compensa?', 'Depois do reajuste, só vale pra quem faz Tóquio–Kyoto–Hiroshima em até 7 dias.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-b1e06e323ae8', now() - interval '8640 minutes', null, 'de300000-0000-4000-8000-4bb1f5f7da2c', 'tip', 'Patagônia', null, 'Laguna de los Tres no outono', 'De abril em diante, saia antes das 7h. O último trecho congela à tarde.', null, '[]'::jsonb, null, 'public'),
  ('de300000-0000-4000-8000-220e64addcac', now() - interval '28800 minutes', null, 'de300000-0000-4000-8000-000000000001', 'tip', 'Lisboa', null, null, 'Pega o elétrico 28 no Martim Moniz antes das 9h: dá pra sentar e ver Alfama com calma.', null, '[]'::jsonb, 'de300000-0000-4000-8000-7856d1b2f3aa', 'public')
on conflict (id) do nothing;

insert into public.comments (id, created_at, deleted_at, post_id, user_id, text) values
  ('de300000-0000-4000-8000-33061566da3d', now() - interval '1440 minutes', null, 'de300000-0000-4000-8000-ec8c9d2ba52c', 'de300000-0000-4000-8000-8b65da21c2e6', 'Confirmo! Fui sábado às 8h40 e sentei na janela.'),
