  ('de300000-0000-4000-8000-4e061a7d7838', now() - interval '4320 minutes', null, 'de300000-0000-4000-8000-ef8c9d2baa45', 'de300000-0000-4000-8000-8492f3476a98', 'Salvei! Arashiyama de semana faz toda a diferença.'),
  ('de300000-0000-4000-8000-01061fcd3247', now() - interval '7200 minutes', null, 'de300000-0000-4000-8000-ee8c9d2ba892', 'de300000-0000-4000-8000-c21114353819', 'Reservei pelo WhatsApp do restaurante, foi rápido.')
